"""Builds content/catalogue.json: the course catalogue outline from brief section 4.

Every subject has Basic, Intermediate and Advanced courses. Each course has 3-6 learning
objectives, modules with estimated minutes, prerequisites, and the format of the content
the company will supply. Company-specific policies, prices and product claims are left as
[PLACEHOLDER] text for the company to fill in. Run: python3 scripts/build-catalogue.py
"""
import json, os

V = "VIDEO (MP4, 720p, with WebVTT captions)"
P = "PDF"
T = "TEXT (written lesson)"
L = "LAB (step-by-step checklist)"
S = "LIVE_SESSION (instructor-led)"

def m(title, minutes, fmt):
    return {"title": title, "minutes": minutes, "content": f"[PLACEHOLDER: company to supply] {fmt}"}

def course(title, desc, objectives, modules, existing=None):
    assert 3 <= len(objectives) <= 6, title
    return {"title": title, "description": desc, "objectives": objectives, "modules": modules, "existingCourse": existing}

def subject(name, category, path_note, basic, inter, adv):
    return {"subject": name, "category": category, "learningPath": path_note,
            "levels": {"BASIC": basic, "INTERMEDIATE": inter, "ADVANCED": adv}}

