for s in CAT:
    s["levels"]["BASIC"]["prerequisites"] = []
    s["levels"]["INTERMEDIATE"]["prerequisites"] = [s["levels"]["BASIC"]["title"]]
    s["levels"]["ADVANCED"]["prerequisites"] = [s["levels"]["INTERMEDIATE"]["title"]]

assert len(CAT) == 17
out = os.path.join(os.path.dirname(__file__), "..", "content", "catalogue.json")
with open(out, "w") as f:
    json.dump({"note": "Course catalogue outline (brief section 4). All content is a placeholder for the company to supply. Generated by scripts/build-catalogue.py.", "subjects": CAT}, f, indent=2, ensure_ascii=False)
    f.write("\n")
print("wrote", out, sum(len(s["levels"]) for s in CAT), "courses")
